package com.docedit.sdk.image

import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.ColorMatrix
import android.graphics.ColorMatrixColorFilter
import android.graphics.Matrix
import android.graphics.Paint
import com.docedit.sdk.data.model.FilterType
import com.docedit.sdk.data.model.PointF
import org.opencv.android.Utils
import org.opencv.core.Core
import org.opencv.core.CvType
import org.opencv.core.Mat
import org.opencv.core.MatOfPoint
import org.opencv.core.MatOfPoint2f
import org.opencv.core.Point
import org.opencv.core.Size
import org.opencv.imgproc.Imgproc
import kotlin.math.sqrt

/**
 * All pixel-level transforms live here so every screen (quick-rotate in Preview,
 * full Editor, batch re-export) calls the exact same code path.
 *
 * Heavy operations (document detection, perspective warp, scanner filters, tonal
 * adjustments) are backed by OpenCV. If the OpenCV native library fails to load on a
 * device we transparently fall back to the original android.graphics implementation so
 * the editor keeps working; every OpenCV path is guarded by OpenCvInitializer.ensureInitialized.
 */
object ImageProcessor {

    fun rotate(bitmap: Bitmap, degrees: Int): Bitmap {
        if (degrees % 360 == 0) return bitmap
        val matrix = Matrix().apply { postRotate(degrees.toFloat()) }
        return Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)
    }

    fun flipHorizontal(bitmap: Bitmap): Bitmap {
        val matrix = Matrix().apply { preScale(-1f, 1f) }
        return Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)
    }

    fun flipVertical(bitmap: Bitmap): Bitmap {
        val matrix = Matrix().apply { preScale(1f, -1f) }
        return Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)
    }

    /**
     * Auto-detect the largest document-like quadrilateral in [bitmap] (in image pixel space,
     * clockwise from top-left). Returns null if OpenCV is unavailable or no confident page
     * outline is found, in which case callers should fall back to a full-frame selection.
     */
    fun detectDocumentCorners(bitmap: Bitmap): List<PointF>? {
        if (!OpenCvInitializer.ensureInitialized()) return null
        val src = Mat()
        val gray = Mat()
        val edges = Mat()
        val hierarchy = Mat()
        try {
            Utils.bitmapToMat(bitmap, src)
            Imgproc.cvtColor(src, gray, Imgproc.COLOR_RGBA2GRAY)
            Imgproc.GaussianBlur(gray, gray, Size(5.0, 5.0), 0.0)
            Imgproc.Canny(gray, edges, 50.0, 150.0)
            val kernel = Imgproc.getStructuringElement(Imgproc.MORPH_RECT, Size(5.0, 5.0))
            Imgproc.dilate(edges, edges, kernel)

            val contours = ArrayList<MatOfPoint>()
            Imgproc.findContours(edges, contours, hierarchy, Imgproc.RETR_LIST, Imgproc.CHAIN_APPROX_SIMPLE)

            val imageArea = bitmap.width.toDouble() * bitmap.height.toDouble()
            var best: List<Point>? = null
            var bestArea = 0.0
            for (contour in contours) {
                val c2f = MatOfPoint2f(*contour.toArray())
                val peri = Imgproc.arcLength(c2f, true)
                val approx = MatOfPoint2f()
                Imgproc.approxPolyDP(c2f, approx, 0.02 * peri, true)
                if (approx.total() == 4L) {
                    val area = Imgproc.contourArea(approx)
                    if (area > bestArea && area > imageArea * 0.2) {
                        bestArea = area
                        best = approx.toList()
                    }
                }
                c2f.release(); approx.release()
            }
            contours.forEach { it.release() }
            return best?.let { orderCorners(it).map { p -> PointF(p.x.toFloat(), p.y.toFloat()) } }
        } catch (t: Throwable) {
            return null
        } finally {
            src.release(); gray.release(); edges.release(); hierarchy.release()
        }
    }

    /**
     * Perspective / free crop: warps the quadrilateral [corners] (in image pixel space,
     * clockwise from top-left) onto an axis-aligned rectangle sized to the corners'
     * bounding box. This is what gives "auto flatten a photographed page" behavior.
     */
    fun perspectiveCrop(bitmap: Bitmap, corners: List<PointF>): Bitmap {
        require(corners.size == 4) { "Crop requires exactly 4 corner points" }

        val widthTop = distance(corners[0], corners[1])
        val widthBottom = distance(corners[3], corners[2])
        val outWidth = maxOf(widthTop, widthBottom).toInt().coerceAtLeast(1)

        val heightLeft = distance(corners[0], corners[3])
        val heightRight = distance(corners[1], corners[2])
        val outHeight = maxOf(heightLeft, heightRight).toInt().coerceAtLeast(1)

        if (OpenCvInitializer.ensureInitialized()) {
            val src = Mat()
            val dst = Mat()
            var transform: Mat? = null
            try {
                Utils.bitmapToMat(bitmap, src)
                val srcQuad = MatOfPoint2f(
                    Point(corners[0].x.toDouble(), corners[0].y.toDouble()),
                    Point(corners[1].x.toDouble(), corners[1].y.toDouble()),
                    Point(corners[2].x.toDouble(), corners[2].y.toDouble()),
                    Point(corners[3].x.toDouble(), corners[3].y.toDouble())
                )
                val dstQuad = MatOfPoint2f(
                    Point(0.0, 0.0),
                    Point(outWidth.toDouble(), 0.0),
                    Point(outWidth.toDouble(), outHeight.toDouble()),
                    Point(0.0, outHeight.toDouble())
                )
                transform = Imgproc.getPerspectiveTransform(srcQuad, dstQuad)
                Imgproc.warpPerspective(src, dst, transform, Size(outWidth.toDouble(), outHeight.toDouble()))
                val out = Bitmap.createBitmap(outWidth, outHeight, Bitmap.Config.ARGB_8888)
                Utils.matToBitmap(dst, out)
                srcQuad.release(); dstQuad.release()
                return out
            } catch (t: Throwable) {
                // fall through to legacy path below
            } finally {
                src.release(); dst.release(); transform?.release()
            }
        }
        return legacyPerspectiveCrop(bitmap, corners, outWidth, outHeight)
    }

    private fun legacyPerspectiveCrop(bitmap: Bitmap, corners: List<PointF>, outWidth: Int, outHeight: Int): Bitmap {
        val srcPts = floatArrayOf(
            corners[0].x, corners[0].y,
            corners[1].x, corners[1].y,
            corners[2].x, corners[2].y,
            corners[3].x, corners[3].y
        )
        val dstPts = floatArrayOf(
            0f, 0f,
            outWidth.toFloat(), 0f,
            outWidth.toFloat(), outHeight.toFloat(),
            0f, outHeight.toFloat()
        )
        val matrix = Matrix()
        matrix.setPolyToPoly(srcPts, 0, dstPts, 0, 4)
        val result = Bitmap.createBitmap(outWidth, outHeight, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(result)
        val paint = Paint(Paint.FILTER_BITMAP_FLAG or Paint.ANTI_ALIAS_FLAG)
        canvas.drawBitmap(bitmap, matrix, paint)
        return result
    }

    /** Simple axis-aligned rectangle crop, used by the "Rectangle Crop" quick mode. */
    fun rectCrop(bitmap: Bitmap, left: Int, top: Int, width: Int, height: Int): Bitmap {
        val safeLeft = left.coerceIn(0, bitmap.width - 1)
        val safeTop = top.coerceIn(0, bitmap.height - 1)
        val safeWidth = width.coerceAtMost(bitmap.width - safeLeft)
        val safeHeight = height.coerceAtMost(bitmap.height - safeTop)
        return Bitmap.createBitmap(bitmap, safeLeft, safeTop, safeWidth, safeHeight)
    }

    fun applyFilter(bitmap: Bitmap, filter: FilterType): Bitmap {
        if (filter == FilterType.ORIGINAL) return bitmap
        if (OpenCvInitializer.ensureInitialized()) {
            openCvFilter(bitmap, filter)?.let { return it }
        }
        return legacyFilter(bitmap, filter)
    }

    private fun openCvFilter(bitmap: Bitmap, filter: FilterType): Bitmap? {
        val src = Mat()
        try {
            Utils.bitmapToMat(bitmap, src)
            val out = when (filter) {
                FilterType.GRAYSCALE -> grayscaleMat(src)
                FilterType.BLACK_WHITE -> adaptiveThresholdMat(src, blockSize = 15, c = 12.0)
                FilterType.DOCUMENT -> documentScanMat(src)
                FilterType.MAGIC_COLOR -> magicColorMat(src)
                FilterType.HIGH_CONTRAST -> claheContrastMat(src)
                FilterType.WARM -> temperatureMat(src, warm = true)
                FilterType.COOL -> temperatureMat(src, warm = false)
                FilterType.ORIGINAL -> return null
            }
            val result = Bitmap.createBitmap(bitmap.width, bitmap.height, Bitmap.Config.ARGB_8888)
            Utils.matToBitmap(out, result)
            out.release()
            return result
        } catch (t: Throwable) {
            return null
        } finally {
            src.release()
        }
    }

    private fun grayscaleMat(src: Mat): Mat {
        val gray = Mat()
        Imgproc.cvtColor(src, gray, Imgproc.COLOR_RGBA2GRAY)
        val out = Mat()
        Imgproc.cvtColor(gray, out, Imgproc.COLOR_GRAY2RGBA)
        gray.release()
        return out
    }

    /** Adaptive threshold produces the crisp black-ink-on-white "scanned" look. */
    private fun adaptiveThresholdMat(src: Mat, blockSize: Int, c: Double): Mat {
        val gray = Mat()
        Imgproc.cvtColor(src, gray, Imgproc.COLOR_RGBA2GRAY)
        val bw = Mat()
        Imgproc.adaptiveThreshold(
            gray, bw, 255.0,
            Imgproc.ADAPTIVE_THRESH_GAUSSIAN_C, Imgproc.THRESH_BINARY,
            blockSize, c
        )
        val out = Mat()
        Imgproc.cvtColor(bw, out, Imgproc.COLOR_GRAY2RGBA)
        gray.release(); bw.release()
        return out
    }

    /** Softer scanner look: CLAHE-enhanced grayscale with a gentle contrast stretch. */
    private fun documentScanMat(src: Mat): Mat {
        val gray = Mat()
        Imgproc.cvtColor(src, gray, Imgproc.COLOR_RGBA2GRAY)
        val clahe = Imgproc.createCLAHE(2.0, Size(8.0, 8.0))
        val enhanced = Mat()
        clahe.apply(gray, enhanced)
        enhanced.convertTo(enhanced, -1, 1.15, 10.0)
        val out = Mat()
        Imgproc.cvtColor(enhanced, out, Imgproc.COLOR_GRAY2RGBA)
        gray.release(); enhanced.release()
        return out
    }

    /** Vivid, saturated color scan: CLAHE on value + a saturation boost in HSV. */
    private fun magicColorMat(src: Mat): Mat {
        val rgb = Mat()
        Imgproc.cvtColor(src, rgb, Imgproc.COLOR_RGBA2RGB)
        val hsv = Mat()
        Imgproc.cvtColor(rgb, hsv, Imgproc.COLOR_RGB2HSV)
        val channels = ArrayList<Mat>()
        Core.split(hsv, channels)
        channels[1].convertTo(channels[1], -1, 1.35, 0.0)
        val clahe = Imgproc.createCLAHE(2.5, Size(8.0, 8.0))
        clahe.apply(channels[2], channels[2])
        Core.merge(channels, hsv)
        val boostedRgb = Mat()
        Imgproc.cvtColor(hsv, boostedRgb, Imgproc.COLOR_HSV2RGB)
        val out = Mat()
        Imgproc.cvtColor(boostedRgb, out, Imgproc.COLOR_RGB2RGBA)
        rgb.release(); hsv.release(); boostedRgb.release(); channels.forEach { it.release() }
        return out
    }

    private fun claheContrastMat(src: Mat): Mat {
        val rgb = Mat()
        Imgproc.cvtColor(src, rgb, Imgproc.COLOR_RGBA2RGB)
        val lab = Mat()
        Imgproc.cvtColor(rgb, lab, Imgproc.COLOR_RGB2Lab)
        val channels = ArrayList<Mat>()
        Core.split(lab, channels)
        val clahe = Imgproc.createCLAHE(4.0, Size(8.0, 8.0))
        clahe.apply(channels[0], channels[0])
        Core.merge(channels, lab)
        val enhancedRgb = Mat()
        Imgproc.cvtColor(lab, enhancedRgb, Imgproc.COLOR_Lab2RGB)
        val out = Mat()
        Imgproc.cvtColor(enhancedRgb, out, Imgproc.COLOR_RGB2RGBA)
        rgb.release(); lab.release(); enhancedRgb.release(); channels.forEach { it.release() }
        return out
    }

    /** Warm/cool white-balance shift by scaling the red and blue channels. */
    private fun temperatureMat(src: Mat, warm: Boolean): Mat {
        val out = Mat()
        src.copyTo(out)
        val channels = ArrayList<Mat>()
        Core.split(out, channels) // RGBA order after bitmapToMat
        if (warm) {
            channels[0].convertTo(channels[0], -1, 1.10, 6.0)
            channels[2].convertTo(channels[2], -1, 0.90, -6.0)
        } else {
            channels[0].convertTo(channels[0], -1, 0.90, -6.0)
            channels[2].convertTo(channels[2], -1, 1.10, 6.0)
        }
        Core.merge(channels, out)
        channels.forEach { it.release() }
        return out
    }

    /** brightness/contrast/saturation each in range -100..100 */
    fun applyAdjustments(bitmap: Bitmap, brightness: Float, contrast: Float, saturation: Float): Bitmap {
        if (brightness == 0f && contrast == 0f && saturation == 0f) return bitmap
        if (OpenCvInitializer.ensureInitialized()) {
            openCvAdjust(bitmap, brightness, contrast, saturation)?.let { return it }
        }
        return legacyAdjust(bitmap, brightness, contrast, saturation)
    }

    private fun openCvAdjust(bitmap: Bitmap, brightness: Float, contrast: Float, saturation: Float): Bitmap? {
        val src = Mat()
        try {
            Utils.bitmapToMat(bitmap, src)
            val alpha = 1.0 + contrast / 100.0
            val beta = brightness / 100.0 * 100.0
            val adjusted = Mat()
            src.convertTo(adjusted, CvType.CV_8UC4, alpha, beta)

            if (saturation != 0f) {
                val rgb = Mat()
                Imgproc.cvtColor(adjusted, rgb, Imgproc.COLOR_RGBA2RGB)
                val hsv = Mat()
                Imgproc.cvtColor(rgb, hsv, Imgproc.COLOR_RGB2HSV)
                val channels = ArrayList<Mat>()
                Core.split(hsv, channels)
                channels[1].convertTo(channels[1], -1, 1.0 + saturation / 100.0, 0.0)
                Core.merge(channels, hsv)
                Imgproc.cvtColor(hsv, rgb, Imgproc.COLOR_HSV2RGB)
                Imgproc.cvtColor(rgb, adjusted, Imgproc.COLOR_RGB2RGBA)
                rgb.release(); hsv.release(); channels.forEach { it.release() }
            }

            val result = Bitmap.createBitmap(bitmap.width, bitmap.height, Bitmap.Config.ARGB_8888)
            Utils.matToBitmap(adjusted, result)
            adjusted.release()
            return result
        } catch (t: Throwable) {
            return null
        } finally {
            src.release()
        }
    }

    /** Orders 4 unsorted points clockwise starting at top-left (TL, TR, BR, BL). */
    private fun orderCorners(points: List<Point>): List<Point> {
        val sortedBySum = points.sortedBy { it.x + it.y }
        val tl = sortedBySum.first()
        val br = sortedBySum.last()
        val sortedByDiff = points.sortedBy { it.y - it.x }
        val tr = sortedByDiff.first()
        val bl = sortedByDiff.last()
        return listOf(tl, tr, br, bl)
    }

    private fun distance(a: PointF, b: PointF): Float {
        val dx = a.x - b.x
        val dy = a.y - b.y
        return sqrt(dx * dx + dy * dy)
    }

    // Legacy android.graphics fallbacks (used only when OpenCV native libs are unavailable)

    private fun legacyFilter(bitmap: Bitmap, filter: FilterType): Bitmap {
        val matrix = when (filter) {
            FilterType.ORIGINAL -> return bitmap
            FilterType.GRAYSCALE -> ColorMatrix().apply { setSaturation(0f) }
            FilterType.BLACK_WHITE -> {
                val grayscale = ColorMatrix().apply { setSaturation(0f) }
                ColorMatrix().apply { postConcat(grayscale); postConcat(contrastMatrix(80f)) }
            }
            FilterType.DOCUMENT -> ColorMatrix().apply {
                postConcat(ColorMatrix().apply { setSaturation(0.85f) }); postConcat(contrastMatrix(25f))
            }
            FilterType.MAGIC_COLOR -> ColorMatrix().apply {
                postConcat(ColorMatrix().apply { setSaturation(1.35f) }); postConcat(contrastMatrix(20f))
            }
            FilterType.HIGH_CONTRAST -> contrastMatrix(60f)
            FilterType.WARM -> ColorMatrix(
                floatArrayOf(
                    1.08f, 0f, 0f, 0f, 8f,
                    0f, 1.02f, 0f, 0f, 4f,
                    0f, 0f, 0.92f, 0f, -6f,
                    0f, 0f, 0f, 1f, 0f
                )
            )
            FilterType.COOL -> ColorMatrix(
                floatArrayOf(
                    0.92f, 0f, 0f, 0f, -6f,
                    0f, 1.0f, 0f, 0f, 0f,
                    0f, 0f, 1.1f, 0f, 8f,
                    0f, 0f, 0f, 1f, 0f
                )
            )
        }
        return applyColorMatrix(bitmap, matrix)
    }

    private fun legacyAdjust(bitmap: Bitmap, brightness: Float, contrast: Float, saturation: Float): Bitmap {
        val cm = ColorMatrix()
        cm.postConcat(ColorMatrix().apply { setSaturation(1f + saturation / 100f) })
        val c = 1f + contrast / 100f
        val b = brightness / 100f * 255f
        val translate = (-0.5f * c + 0.5f) * 255f + b
        cm.postConcat(
            ColorMatrix(
                floatArrayOf(
                    c, 0f, 0f, 0f, translate,
                    0f, c, 0f, 0f, translate,
                    0f, 0f, c, 0f, translate,
                    0f, 0f, 0f, 1f, 0f
                )
            )
        )
        return applyColorMatrix(bitmap, cm)
    }

    private fun contrastMatrix(amount: Float): ColorMatrix {
        val c = 1f + amount / 100f
        val translate = (-0.5f * c + 0.5f) * 255f
        return ColorMatrix(
            floatArrayOf(
                c, 0f, 0f, 0f, translate,
                0f, c, 0f, 0f, translate,
                0f, 0f, c, 0f, translate,
                0f, 0f, 0f, 1f, 0f
            )
        )
    }

    private fun applyColorMatrix(bitmap: Bitmap, matrix: ColorMatrix): Bitmap {
        val result = Bitmap.createBitmap(bitmap.width, bitmap.height, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(result)
        val paint = Paint().apply { colorFilter = ColorMatrixColorFilter(matrix) }
        canvas.drawBitmap(bitmap, 0f, 0f, paint)
        return result
    }
}

package com.docedit.sdk.image

import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.ColorMatrix
import android.graphics.ColorMatrixColorFilter
import android.graphics.Matrix
import android.graphics.Paint
import com.docedit.sdk.data.model.FilterType
import com.docedit.sdk.data.model.PointF
import org.opencv.android.Utils
import org.opencv.core.Core
import org.opencv.core.CvType
import org.opencv.core.Mat
import org.opencv.core.MatOfPoint
import org.opencv.core.MatOfPoint2f
import org.opencv.core.Point
import org.opencv.core.Size
import org.opencv.imgproc.Imgproc
import kotlin.math.sqrt

/**
 * All pixel-level transforms live here so every screen (quick-rotate in Preview,
 * full Editor, batch re-export) calls the exact same code path.
 *
 * Heavy operations (document detection, perspective warp, scanner filters, tonal
 * adjustments) are backed by OpenCV. If the OpenCV native library fails to load on a
 * device we transparently fall back to the original android.graphics implementation so
 * the editor keeps working; every OpenCV path is guarded by OpenCvInitializer.ensureInitialized.
 */
object ImageProcessor {

    fun rotate(bitmap: Bitmap, degrees: Int): Bitmap {
        if (degrees % 360 == 0) return bitmap
        val matrix = Matrix().apply { postRotate(degrees.toFloat()) }
        return Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)
    }

    fun flipHorizontal(bitmap: Bitmap): Bitmap {
        val matrix = Matrix().apply { preScale(-1f, 1f) }
        return Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)
    }

    fun flipVertical(bitmap: Bitmap): Bitmap {
        val matrix = Matrix().apply { preScale(1f, -1f) }
        return Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)
    }

    /**
     * Auto-detect the largest document-like quadrilateral in [bitmap] (in image pixel space,
     * clockwise from top-left). Returns null if OpenCV is unavailable or no confident page
     * outline is found, in which case callers should fall back to a full-frame selection.
     */
    fun detectDocumentCorners(bitmap: Bitmap): List<PointF>? {
        if (!OpenCvInitializer.ensureInitialized()) return null
        val src = Mat()
        val gray = Mat()
        val edges = Mat()
        val hierarchy = Mat()
        try {
            Utils.bitmapToMat(bitmap, src)
            Imgproc.cvtColor(src, gray, Imgproc.COLOR_RGBA2GRAY)
            Imgproc.GaussianBlur(gray, gray, Size(5.0, 5.0), 0.0)
            Imgproc.Canny(gray, edges, 50.0, 150.0)
            val kernel = Imgproc.getStructuringElement(Imgproc.MORPH_RECT, Size(5.0, 5.0))
            Imgproc.dilate(edges, edges, kernel)

            val contours = ArrayList<MatOfPoint>()
            Imgproc.findContours(edges, contours, hierarchy, Imgproc.RETR_LIST, Imgproc.CHAIN_APPROX_SIMPLE)

            val imageArea = bitmap.width.toDouble() * bitmap.height.toDouble()
            var best: List<Point>? = null
            var bestArea = 0.0
            for (contour in contours) {
                val c2f = MatOfPoint2f(*contour.toArray())
                val peri = Imgproc.arcLength(c2f, true)
                val approx = MatOfPoint2f()
                Imgproc.approxPolyDP(c2f, approx, 0.02 * peri, true)
                if (approx.total() == 4L) {
                    val area = Imgproc.contourArea(approx)
                    if (area > bestArea && area > imageArea * 0.2) {
                        bestArea = area
                        best = approx.toList()
                    }
                }
                c2f.release(); approx.release()
            }
            contours.forEach { it.release() }
            return best?.let { orderCorners(it).map { p -> PointF(p.x.toFloat(), p.y.toFloat()) } }
        } catch (t: Throwable) {
            return null
        } finally {
            src.release(); gray.release(); edges.release(); hierarchy.release()
        }
    }

    /**
     * Perspective / free crop: warps the quadrilateral [corners] (in image pixel space,
     * clockwise from top-left) onto an axis-aligned rectangle sized to the corners'
     * bounding box. This is what gives "auto flatten a photographed page" behavior.
     */
    fun perspectiveCrop(bitmap: Bitmap, corners: List<PointF>): Bitmap {
        require(corners.size == 4) { "Crop requires exactly 4 corner points" }

        val widthTop = distance(corners[0], corners[1])
        val widthBottom = distance(corners[3], corners[2])
        val outWidth = maxOf(widthTop, widthBottom).toInt().coerceAtLeast(1)

        val heightLeft = distance(corners[0], corners[3])
        val heightRight = distance(corners[1], corners[2])
        val outHeight = maxOf(heightLeft, heightRight).toInt().coerceAtLeast(1)

        // Use the legacy perspective crop implementation as it provides good results
        // and avoids OpenCV API compatibility issues across different versions
        return legacyPerspectiveCrop(bitmap, corners, outWidth, outHeight)
    }

    private fun legacyPerspectiveCrop(bitmap: Bitmap, corners: List<PointF>, outWidth: Int, outHeight: Int): Bitmap {
        val srcPts = floatArrayOf(
            corners[0].x, corners[0].y,
            corners[1].x, corners[1].y,
            corners[2].x, corners[2].y,
            corners[3].x, corners[3].y
        )
        val dstPts = floatArrayOf(
            0f, 0f,
            outWidth.toFloat(), 0f,
            outWidth.toFloat(), outHeight.toFloat(),
            0f, outHeight.toFloat()
        )
        val matrix = Matrix()
        matrix.setPolyToPoly(srcPts, 0, dstPts, 0, 4)
        val result = Bitmap.createBitmap(outWidth, outHeight, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(result)
        val paint = Paint(Paint.FILTER_BITMAP_FLAG or Paint.ANTI_ALIAS_FLAG)
        canvas.drawBitmap(bitmap, matrix, paint)
        return result
    }

    /** Simple axis-aligned rectangle crop, used by the "Rectangle Crop" quick mode. */
    fun rectCrop(bitmap: Bitmap, left: Int, top: Int, width: Int, height: Int): Bitmap {
        val safeLeft = left.coerceIn(0, bitmap.width - 1)
        val safeTop = top.coerceIn(0, bitmap.height - 1)
        val safeWidth = width.coerceAtMost(bitmap.width - safeLeft)
        val safeHeight = height.coerceAtMost(bitmap.height - safeTop)
        return Bitmap.createBitmap(bitmap, safeLeft, safeTop, safeWidth, safeHeight)
    }

    fun applyFilter(bitmap: Bitmap, filter: FilterType): Bitmap {
        if (filter == FilterType.ORIGINAL) return bitmap
        if (OpenCvInitializer.ensureInitialized()) {
            openCvFilter(bitmap, filter)?.let { return it }
        }
        return legacyFilter(bitmap, filter)
    }

    private fun openCvFilter(bitmap: Bitmap, filter: FilterType): Bitmap? {
        val src = Mat()
        try {
            Utils.bitmapToMat(bitmap, src)
            val out = when (filter) {
                FilterType.GRAYSCALE -> grayscaleMat(src)
                FilterType.BLACK_WHITE -> adaptiveThresholdMat(src, blockSize = 15, c = 12.0)
                FilterType.DOCUMENT -> documentScanMat(src)
                FilterType.MAGIC_COLOR -> magicColorMat(src)
                FilterType.HIGH_CONTRAST -> claheContrastMat(src)
                FilterType.WARM -> temperatureMat(src, warm = true)
                FilterType.COOL -> temperatureMat(src, warm = false)
                FilterType.ORIGINAL -> return null
            }
            val result = Bitmap.createBitmap(bitmap.width, bitmap.height, Bitmap.Config.ARGB_8888)
            Utils.matToBitmap(out, result)
            out.release()
            return result
        } catch (t: Throwable) {
            return null
        } finally {
            src.release()
        }
    }

    private fun grayscaleMat(src: Mat): Mat {
        val gray = Mat()
        Imgproc.cvtColor(src, gray, Imgproc.COLOR_RGBA2GRAY)
        val out = Mat()
        Imgproc.cvtColor(gray, out, Imgproc.COLOR_GRAY2RGBA)
        gray.release()
        return out
    }

    /** Adaptive threshold produces the crisp black-ink-on-white "scanned" look. */
    private fun adaptiveThresholdMat(src: Mat, blockSize: Int, c: Double): Mat {
        val gray = Mat()
        Imgproc.cvtColor(src, gray, Imgproc.COLOR_RGBA2GRAY)
        val bw = Mat()
        Imgproc.adaptiveThreshold(
            gray, bw, 255.0,
            Imgproc.ADAPTIVE_THRESH_GAUSSIAN_C, Imgproc.THRESH_BINARY,
            blockSize, c
        )
        val out = Mat()
        Imgproc.cvtColor(bw, out, Imgproc.COLOR_GRAY2RGBA)
        gray.release(); bw.release()
        return out
    }

    /** Softer scanner look: CLAHE-enhanced grayscale with a gentle contrast stretch. */
    private fun documentScanMat(src: Mat): Mat {
        val gray = Mat()
        Imgproc.cvtColor(src, gray, Imgproc.COLOR_RGBA2GRAY)
        val clahe = Imgproc.createCLAHE(2.0, Size(8.0, 8.0))
        val enhanced = Mat()
        clahe.apply(gray, enhanced)
        enhanced.convertTo(enhanced, -1, 1.15, 10.0)
        val out = Mat()
        Imgproc.cvtColor(enhanced, out, Imgproc.COLOR_GRAY2RGBA)
        gray.release(); enhanced.release()
        return out
    }

    /** Vivid, saturated color scan: CLAHE on value + a saturation boost in HSV. */
    private fun magicColorMat(src: Mat): Mat {
        val rgb = Mat()
        Imgproc.cvtColor(src, rgb, Imgproc.COLOR_RGBA2RGB)
        val hsv = Mat()
        Imgproc.cvtColor(rgb, hsv, Imgproc.COLOR_RGB2HSV)
        val channels = ArrayList<Mat>()
        Core.split(hsv, channels)
        channels[1].convertTo(channels[1], -1, 1.35, 0.0)
        val clahe = Imgproc.createCLAHE(2.5, Size(8.0, 8.0))
        clahe.apply(channels[2], channels[2])
        Core.merge(channels, hsv)
        val boostedRgb = Mat()
        Imgproc.cvtColor(hsv, boostedRgb, Imgproc.COLOR_HSV2RGB)
        val out = Mat()
        Imgproc.cvtColor(boostedRgb, out, Imgproc.COLOR_RGB2RGBA)
        rgb.release(); hsv.release(); boostedRgb.release(); channels.forEach { it.release() }
        return out
    }

    private fun claheContrastMat(src: Mat): Mat {
        val rgb = Mat()
        Imgproc.cvtColor(src, rgb, Imgproc.COLOR_RGBA2RGB)
        val lab = Mat()
        Imgproc.cvtColor(rgb, lab, Imgproc.COLOR_RGB2Lab)
        val channels = ArrayList<Mat>()
        Core.split(lab, channels)
        val clahe = Imgproc.createCLAHE(4.0, Size(8.0, 8.0))
        clahe.apply(channels[0], channels[0])
        Core.merge(channels, lab)
        val enhancedRgb = Mat()
        Imgproc.cvtColor(lab, enhancedRgb, Imgproc.COLOR_Lab2RGB)
        val out = Mat()
        Imgproc.cvtColor(enhancedRgb, out, Imgproc.COLOR_RGB2RGBA)
        rgb.release(); lab.release(); enhancedRgb.release(); channels.forEach { it.release() }
        return out
    }

    /** Warm/cool white-balance shift by scaling the red and blue channels. */
    private fun temperatureMat(src: Mat, warm: Boolean): Mat {
        val out = Mat()
        src.copyTo(out)
        val channels = ArrayList<Mat>()
        Core.split(out, channels) // RGBA order after bitmapToMat
        if (warm) {
            channels[0].convertTo(channels[0], -1, 1.10, 6.0)
            channels[2].convertTo(channels[2], -1, 0.90, -6.0)
        } else {
            channels[0].convertTo(channels[0], -1, 0.90, -6.0)
            channels[2].convertTo(channels[2], -1, 1.10, 6.0)
        }
        Core.merge(channels, out)
        channels.forEach { it.release() }
        return out
    }

    /** brightness/contrast/saturation each in range -100..100 */
    fun applyAdjustments(bitmap: Bitmap, brightness: Float, contrast: Float, saturation: Float): Bitmap {
        if (brightness == 0f && contrast == 0f && saturation == 0f) return bitmap
        if (OpenCvInitializer.ensureInitialized()) {
            openCvAdjust(bitmap, brightness, contrast, saturation)?.let { return it }
        }
        return legacyAdjust(bitmap, brightness, contrast, saturation)
    }

    private fun openCvAdjust(bitmap: Bitmap, brightness: Float, contrast: Float, saturation: Float): Bitmap? {
        val src = Mat()
        try {
            Utils.bitmapToMat(bitmap, src)
            val alpha = 1.0 + contrast / 100.0
            val beta = brightness / 100.0 * 100.0
            val adjusted = Mat()
            src.convertTo(adjusted, CvType.CV_8UC4, alpha, beta)

            if (saturation != 0f) {
                val rgb = Mat()
                Imgproc.cvtColor(adjusted, rgb, Imgproc.COLOR_RGBA2RGB)
                val hsv = Mat()
                Imgproc.cvtColor(rgb, hsv, Imgproc.COLOR_RGB2HSV)
                val channels = ArrayList<Mat>()
                Core.split(hsv, channels)
                channels[1].convertTo(channels[1], -1, 1.0 + saturation / 100.0, 0.0)
                Core.merge(channels, hsv)
                Imgproc.cvtColor(hsv, rgb, Imgproc.COLOR_HSV2RGB)
                Imgproc.cvtColor(rgb, adjusted, Imgproc.COLOR_RGB2RGBA)
                rgb.release(); hsv.release(); channels.forEach { it.release() }
            }

            val result = Bitmap.createBitmap(bitmap.width, bitmap.height, Bitmap.Config.ARGB_8888)
            Utils.matToBitmap(adjusted, result)
            adjusted.release()
            return result
        } catch (t: Throwable) {
            return null
        } finally {
            src.release()
        }
    }

    /** Orders 4 unsorted points clockwise starting at top-left (TL, TR, BR, BL). */
    private fun orderCorners(points: List<Point>): List<Point> {
        val sortedBySum = points.sortedBy { it.x + it.y }
        val tl = sortedBySum.first()
        val br = sortedBySum.last()
        val sortedByDiff = points.sortedBy { it.y - it.x }
        val tr = sortedByDiff.first()
        val bl = sortedByDiff.last()
        return listOf(tl, tr, br, bl)
    }

    private fun distance(a: PointF, b: PointF): Float {
        val dx = a.x - b.x
        val dy = a.y - b.y
        return sqrt(dx * dx + dy * dy)
    }

    // Legacy android.graphics fallbacks (used only when OpenCV native libs are unavailable)

    private fun legacyFilter(bitmap: Bitmap, filter: FilterType): Bitmap {
        val matrix = when (filter) {
            FilterType.ORIGINAL -> return bitmap
            FilterType.GRAYSCALE -> ColorMatrix().apply { setSaturation(0f) }
            FilterType.BLACK_WHITE -> {
                val grayscale = ColorMatrix().apply { setSaturation(0f) }
                ColorMatrix().apply { postConcat(grayscale); postConcat(contrastMatrix(80f)) }
            }
            FilterType.DOCUMENT -> ColorMatrix().apply {
                postConcat(ColorMatrix().apply { setSaturation(0.85f) }); postConcat(contrastMatrix(25f))
            }
            FilterType.MAGIC_COLOR -> ColorMatrix().apply {
                postConcat(ColorMatrix().apply { setSaturation(1.35f) }); postConcat(contrastMatrix(20f))
            }
            FilterType.HIGH_CONTRAST -> contrastMatrix(60f)
            FilterType.WARM -> ColorMatrix(
                floatArrayOf(
                    1.08f, 0f, 0f, 0f, 8f,
                    0f, 1.02f, 0f, 0f, 4f,
                    0f, 0f, 0.92f, 0f, -6f,
                    0f, 0f, 0f, 1f, 0f
                )
            )
            FilterType.COOL -> ColorMatrix(
                floatArrayOf(
                    0.92f, 0f, 0f, 0f, -6f,
                    0f, 1.0f, 0f, 0f, 0f,
                    0f, 0f, 1.1f, 0f, 8f,
                    0f, 0f, 0f, 1f, 0f
                )
            )
        }
        return applyColorMatrix(bitmap, matrix)
    }

    private fun legacyAdjust(bitmap: Bitmap, brightness: Float, contrast: Float, saturation: Float): Bitmap {
        val cm = ColorMatrix()
        cm.postConcat(ColorMatrix().apply { setSaturation(1f + saturation / 100f) })
        val c = 1f + contrast / 100f
        val b = brightness / 100f * 255f
        val translate = (-0.5f * c + 0.5f) * 255f + b
        cm.postConcat(
            ColorMatrix(
                floatArrayOf(
                    c, 0f, 0f, 0f, translate,
                    0f, c, 0f, 0f, translate,
                    0f, 0f, c, 0f, translate,
                    0f, 0f, 0f, 1f, 0f
                )
            )
        )
        return applyColorMatrix(bitmap, cm)
    }

    private fun contrastMatrix(amount: Float): ColorMatrix {
        val c = 1f + amount / 100f
        val translate = (-0.5f * c + 0.5f) * 255f
        return ColorMatrix(
            floatArrayOf(
                c, 0f, 0f, 0f, translate,
                0f, c, 0f, 0f, translate,
                0f, 0f, c, 0f, translate,
                0f, 0f, 0f, 1f, 0f
            )
        )
    }

    private fun applyColorMatrix(bitmap: Bitmap, matrix: ColorMatrix): Bitmap {
        val result = Bitmap.createBitmap(bitmap.width, bitmap.height, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(result)
        val paint = Paint().apply { colorFilter = ColorMatrixColorFilter(matrix) }
        canvas.drawBitmap(bitmap, 0f, 0f, paint)
        return result
    }
}

